mapper.select:
select
    mn.*
from sys_portal_index_config mn
where 1=1

    and mn.Create_Uid = #{params.createUid}


    and mn.state = #{params.state}


    and mn.Portal_State = #{params.portalState}


    and mn.Create_Uname like concat('%',#{params.createUname},'%')


    and mn.Portal_Name like concat('%',#{params.portalName},'%')


    and mn.Portal_Code like concat('%',#{params.portalCode},'%')


    and mn.System_Identifier = #{params.systemIdentifier}


    
        order by mn.${params.sortFiled} ${params.sortType}
    
    
        order by mn.Create_Time DESC
